using System;

namespace Realmkeeper.Domain.Identifiers
{
    /// <summary>
    /// Stable, GUID-based identifier. Never derived from display names.
    /// Generated by <see cref="Realmkeeper.Domain.Randomness.DeterministicGuid"/> during
    /// world generation/simulation so identical seeds reproduce identical identifiers.
    /// </summary>
    public readonly struct TransactionId : IEquatable<TransactionId>, IComparable<TransactionId>
    {
        public Guid Value { get; }

        public TransactionId(Guid value)
        {
            Value = value;
        }

        public static TransactionId Empty => default;

        public bool IsEmpty => Value == Guid.Empty;

        /// <summary>Creates a random (non-deterministic) identifier. Use only outside simulation/generation.</summary>
        public static TransactionId NewRandom() => new TransactionId(Guid.NewGuid());

        public static TransactionId Parse(string text) => new TransactionId(Guid.Parse(text));

        public static bool TryParse(string text, out TransactionId id)
        {
            if (Guid.TryParse(text, out var guid))
            {
                id = new TransactionId(guid);
                return true;
            }

            id = Empty;
            return false;
        }

        public bool Equals(TransactionId other) => Value.Equals(other.Value);

        public override bool Equals(object obj) => obj is TransactionId other && Equals(other);

        public override int GetHashCode() => Value.GetHashCode();

        public int CompareTo(TransactionId other) => Value.CompareTo(other.Value);

        public override string ToString() => Value.ToString("D");

        public static bool operator ==(TransactionId left, TransactionId right) => left.Equals(right);

        public static bool operator !=(TransactionId left, TransactionId right) => !left.Equals(right);
    }
}
